#include <iostream>
#include <iomanip>
#include <stdexcept>

class Time {
public:
    Time(int h = 0, int m = 0, int s = 0) {
        setTime(h, m, s);
    }

    void setTime(int h, int m, int s) {
        setHour(h);
        setMinute(m);
        setSecond(s);
    }

    void setHour(int h) {
        if (h >= 0 && h < 24) {
            hour = h;
        } else {
            throw std::invalid_argument("hour must be 0-23");
        }
    }

    void setMinute(int m) {
        if (m >= 0 && m < 60) {
            minute = m;
        } else {
            throw std::invalid_argument("minute must be 0-59");
        }
    }

    void setSecond(int s) {
        if (s >= 0 && s < 60) {
            second = s;
        } else {
            throw std::invalid_argument("second must be 0-59");
        }
    }

    int getHour() const { return hour; }
    int getMinute() const { return minute; }
    int getSecond() const { return second; }

    void printUniversal() const {
        std::cout << std::setfill('0') << std::setw(2) << getHour() << ":"
                  << std::setw(2) << getMinute() << ":"
                  << std::setw(2) << getSecond();
    }

    void printStandard() const {
        int h = getHour();
        std::cout << ((h == 0 || h == 12) ? 12 : h % 12) << ":"
                  << std::setfill('0') << std::setw(2) << getMinute() << ":"
                  << std::setw(2) << getSecond() << (h < 12 ? " AM" : " PM");
    }

private:
    int hour{0};
    int minute{0};
    int second{0};
};

int main() {
    Time t1;
    Time t2(14, 5, 9);

    t1.printUniversal();
    std::cout << " | ";
    t1.printStandard();
    std::cout << "\n";

    t2.printUniversal();
    std::cout << " | ";
    t2.printStandard();
    std::cout << "\n";

    try {
        Time tBad(25, 10, 0);
    } catch (const std::invalid_argument& ex) {
        std::cout << "Caught: " << ex.what() << "\n";
    }

    return 0;
}

#include <iostream>
#include <iomanip>

class Time {
public:
    // Delegating constructors routing to the canonical 3-parameter constructor
    Time() : Time(0, 0, 0) {}
    Time(int h) : Time(h, 0, 0) {}
    Time(int h, int m) : Time(h, m, 0) {}

    // Target constructor with in-body initialization / validation
    Time(int h, int m, int s) {
        setTime(h, m, s);
    }

    void setTime(int h, int m, int s) {
        hour = (h >= 0 && h < 24) ? h : 0;
        minute = (m >= 0 && m < 60) ? m : 0;
        second = (s >= 0 && s < 60) ? s : 0;
    }

    void printUniversal() const {
        std::cout << std::setfill('0') << std::setw(2) << hour << ":"
                  << std::setw(2) << minute << ":"
                  << std::setw(2) << second << "\n";
    }

private:
    int hour{0};
    int minute{0};
    int second{0};
};

int main() {
    // C++11 brace list-initialization syntax
    Time t1{};            // Default
    Time t2{8};           // 8:00:00
    Time t3{13, 45};      // 13:45:00
    Time t4{23, 59, 59};  // 23:59:59

    t1.printUniversal();
    t2.printUniversal();
    t3.printUniversal();
    t4.printUniversal();

    return 0;
}
